{
 "cases": [
  {
   "name": "模型不存在",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": null,
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_not_found"
  },
  {
   "name": "Key 无权访问模型",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "limited",
   "body": null,
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_not_allowed"
  },
  {
   "name": "模型类型和接口不匹配",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-backup",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ]
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_kind_mismatch"
  },
  {
   "name": "图片输入，模型不支持图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-vl",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     },
     {
      "role": "assistant",
      "content": "这是图片",
      "image_url": {
       "url": "http://example.com/image.jpg"
      }
     }
    ]
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "image_not_supported"
  },
  {
   "name": "消息内容包含拦截词",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好，我今天看到了一个非常有趣的视频"
     }
    ]
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "content_filter"
  },
  {
   "name": "模型不存在",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": null,
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_not_found"
  },
  {
   "name": "Key 无权访问模型",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "limited",
   "body": null,
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_not_allowed"
  },
  {
   "name": "模型类型和接口不匹配",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-backup",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ]
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_kind_mismatch"
  }
 ]}
